-- SOURCE: supabase/migrations/007_property_intelligence_reports.sql
-- V0.3.2: Property Intelligence Reports Table
-- PETER AGENTIC V0.3.2

-- =============================================================================
-- PROPERTY INTELLIGENCE REPORTS
-- Stores comprehensive property analysis from V0.3.2 pipeline
-- =============================================================================

CREATE TABLE IF NOT EXISTS property_intelligence_reports (
    id BIGSERIAL PRIMARY KEY,
    listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,

    -- Report data (full PropertyIntelligenceReport JSON)
    report_data JSONB NOT NULL,

    -- Key attributes extracted for quick access
    year_built INTEGER,
    year_source TEXT CHECK (year_source IN ('cadastre', 'listing', 'estimate')),
    energy_rating TEXT,
    energy_expected TEXT,
    finish_tier TEXT CHECK (finish_tier IN ('builder_grade', 'mid_range', 'high_end', 'luxury')),
    dominant_style TEXT,
    construction_era TEXT,

    -- Comparison attributes (JSONB for flexibility)
    comparison_attributes JSONB,

    -- Triggers identified
    triggers JSONB,
    trigger_count INTEGER DEFAULT 0,

    -- Regulatory assessment
    regulatory_assessment JSONB,
    has_cte_concerns BOOLEAN DEFAULT FALSE,
    has_rebt_concerns BOOLEAN DEFAULT FALSE,
    has_ite_concerns BOOLEAN DEFAULT FALSE,

    -- Rooms analyzed
    rooms_analyzed JSONB,
    room_count INTEGER DEFAULT 0,

    -- Metadata
    version TEXT DEFAULT 'v0.3.2',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),

    -- Ensure one report per listing
    UNIQUE(listing_id)
);

-- Index for quick lookups
CREATE INDEX IF NOT EXISTS idx_pir_listing ON property_intelligence_reports(listing_id);
CREATE INDEX IF NOT EXISTS idx_pir_energy ON property_intelligence_reports(energy_rating);
CREATE INDEX IF NOT EXISTS idx_pir_finish ON property_intelligence_reports(finish_tier);
CREATE INDEX IF NOT EXISTS idx_pir_era ON property_intelligence_reports(construction_era);

-- Full text search on report data
CREATE INDEX IF NOT EXISTS idx_pir_report_gin ON property_intelligence_reports USING GIN (report_data);

-- =============================================================================
-- COMPARATIVE GAP ANALYSES
-- Stores gap analysis results between target and comparables
-- =============================================================================

CREATE TABLE IF NOT EXISTS comparative_gap_analyses (
    id BIGSERIAL PRIMARY KEY,
    target_listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,
    comparable_listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,

    -- Gap analysis data
    analysis_data JSONB NOT NULL,

    -- Summary fields
    gap_letters INTEGER,  -- Energy rating gap
    scope_level TEXT CHECK (scope_level IN ('cosmetic', 'moderate', 'comprehensive', 'full_gut')),
    intervention_count INTEGER DEFAULT 0,

    -- All intervention IDs (for KG lookup)
    intervention_ids TEXT[],

    -- Permits required
    permits_required JSONB,

    -- Risk factors
    risk_factors JSONB,

    -- Metadata
    version TEXT DEFAULT 'v0.3.2',
    created_at TIMESTAMPTZ DEFAULT NOW(),

    -- Unique constraint per target-comparable pair
    UNIQUE(target_listing_id, comparable_listing_id)
);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_cga_target ON comparative_gap_analyses(target_listing_id);
CREATE INDEX IF NOT EXISTS idx_cga_comparable ON comparative_gap_analyses(comparable_listing_id);
CREATE INDEX IF NOT EXISTS idx_cga_scope ON comparative_gap_analyses(scope_level);

-- =============================================================================
-- AGGREGATED GAP ANALYSES
-- Stores aggregated gap analysis from multiple comparables
-- =============================================================================

CREATE TABLE IF NOT EXISTS aggregated_gap_analyses (
    id BIGSERIAL PRIMARY KEY,
    target_listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,

    -- Comparables used
    comparable_listing_ids BIGINT[] NOT NULL,
    comparable_count INTEGER NOT NULL,

    -- Aggregated results
    aggregated_data JSONB NOT NULL,

    -- Consensus values
    scope_level_consensus TEXT CHECK (scope_level_consensus IN ('cosmetic', 'moderate', 'comprehensive', 'full_gut')),
    total_intervention_count INTEGER DEFAULT 0,
    energy_gap_letters INTEGER,

    -- All intervention IDs (union across all comparisons)
    all_intervention_ids TEXT[],

    -- Metadata
    version TEXT DEFAULT 'v0.3.2',
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),

    -- One aggregated analysis per target
    UNIQUE(target_listing_id)
);

-- Indexes
CREATE INDEX IF NOT EXISTS idx_aga_target ON aggregated_gap_analyses(target_listing_id);
CREATE INDEX IF NOT EXISTS idx_aga_scope ON aggregated_gap_analyses(scope_level_consensus);

-- =============================================================================
-- TRIGGER FOR updated_at
-- =============================================================================

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ language 'plpgsql';

-- Apply to property_intelligence_reports
DROP TRIGGER IF EXISTS update_pir_updated_at ON property_intelligence_reports;
CREATE TRIGGER update_pir_updated_at
    BEFORE UPDATE ON property_intelligence_reports
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-- Apply to aggregated_gap_analyses
DROP TRIGGER IF EXISTS update_aga_updated_at ON aggregated_gap_analyses;
CREATE TRIGGER update_aga_updated_at
    BEFORE UPDATE ON aggregated_gap_analyses
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-- =============================================================================
-- ROW LEVEL SECURITY
-- =============================================================================

ALTER TABLE property_intelligence_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE comparative_gap_analyses ENABLE ROW LEVEL SECURITY;
ALTER TABLE aggregated_gap_analyses ENABLE ROW LEVEL SECURITY;

-- Allow read access to all authenticated users
CREATE POLICY "Allow read access" ON property_intelligence_reports
    FOR SELECT USING (true);
CREATE POLICY "Allow read access" ON comparative_gap_analyses
    FOR SELECT USING (true);
CREATE POLICY "Allow read access" ON aggregated_gap_analyses
    FOR SELECT USING (true);

-- Allow insert/update for service role
CREATE POLICY "Allow service insert" ON property_intelligence_reports
    FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow service update" ON property_intelligence_reports
    FOR UPDATE USING (true);
CREATE POLICY "Allow service insert" ON comparative_gap_analyses
    FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow service insert" ON aggregated_gap_analyses
    FOR INSERT WITH CHECK (true);
CREATE POLICY "Allow service update" ON aggregated_gap_analyses
    FOR UPDATE USING (true);

-- =============================================================================
-- COMMENTS
-- =============================================================================

COMMENT ON TABLE property_intelligence_reports IS 'V0.3.2 Property Intelligence Reports - comprehensive property analysis';
COMMENT ON TABLE comparative_gap_analyses IS 'V0.3.2 Comparative Gap Analyses - individual target vs comparable comparisons';
COMMENT ON TABLE aggregated_gap_analyses IS 'V0.3.2 Aggregated Gap Analyses - combined analysis from multiple comparables';

-- SOURCE: supabase/migrations/007_due_diligence_research.sql
-- Migration: Due Diligence Research Table
-- Section 3: Comprehensive property due diligence with AI-generated queries

-- Create the due_diligence_research table
CREATE TABLE IF NOT EXISTS due_diligence_research (
    id BIGSERIAL PRIMARY KEY,
    listing_id BIGINT NOT NULL REFERENCES listings(id) ON DELETE CASCADE,

    -- Overall risk assessment
    overall_risk_score NUMERIC(5,2),  -- 0-100
    overall_risk_level TEXT CHECK (overall_risk_level IN ('low', 'medium', 'high', 'critical', 'unknown')),

    -- Category results (JSONB array of category findings)
    categories JSONB NOT NULL DEFAULT '[]'::jsonb,

    -- All sources combined (JSONB array for easy querying)
    all_sources JSONB NOT NULL DEFAULT '[]'::jsonb,

    -- Query stats
    total_queries INTEGER DEFAULT 0,
    total_sources INTEGER DEFAULT 0,

    -- Property context used for generation
    property_context JSONB,

    -- Model/processing info
    model_used TEXT,
    processing_time_ms INTEGER,

    -- Timestamps
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),

    -- Ensure one record per listing
    CONSTRAINT unique_due_diligence_per_listing UNIQUE (listing_id)
);

-- Create indexes for common queries
CREATE INDEX IF NOT EXISTS idx_due_diligence_listing_id ON due_diligence_research(listing_id);
CREATE INDEX IF NOT EXISTS idx_due_diligence_risk_level ON due_diligence_research(overall_risk_level);
CREATE INDEX IF NOT EXISTS idx_due_diligence_created_at ON due_diligence_research(created_at DESC);

-- Index for searching within categories JSONB
CREATE INDEX IF NOT EXISTS idx_due_diligence_categories ON due_diligence_research USING GIN (categories);

-- Function to update updated_at timestamp
CREATE OR REPLACE FUNCTION update_due_diligence_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger for automatic updated_at
DROP TRIGGER IF EXISTS trigger_due_diligence_updated_at ON due_diligence_research;
CREATE TRIGGER trigger_due_diligence_updated_at
    BEFORE UPDATE ON due_diligence_research
    FOR EACH ROW
    EXECUTE FUNCTION update_due_diligence_updated_at();

-- Enable RLS
ALTER TABLE due_diligence_research ENABLE ROW LEVEL SECURITY;

-- RLS Policies (allow all for now, can be restricted later)
DROP POLICY IF EXISTS "Allow all access to due_diligence_research" ON due_diligence_research;
CREATE POLICY "Allow all access to due_diligence_research"
    ON due_diligence_research
    FOR ALL
    USING (true)
    WITH CHECK (true);

-- Comments
COMMENT ON TABLE due_diligence_research IS 'Section 3: AI-powered property due diligence across 7 mega-categories';
COMMENT ON COLUMN due_diligence_research.categories IS 'Array of category results with findings, sources, and risk levels';
COMMENT ON COLUMN due_diligence_research.all_sources IS 'Flattened array of all sources for easy UI rendering';
COMMENT ON COLUMN due_diligence_research.overall_risk_score IS 'Weighted average risk score across all categories (0-100)';

-- SOURCE: supabase/migrations/009_comparables_tables.sql
-- Migration: 009_comparables_tables.sql
-- Purpose: Store market comparables data and bracket analyses
-- Created: 2026-01-07

-- =============================================================================
-- TABLE: listing_market_stats
-- Stores Casafari market statistics and price estimates
-- =============================================================================

CREATE TABLE IF NOT EXISTS listing_market_stats (
    listing_id BIGINT PRIMARY KEY REFERENCES listings(id) ON DELETE CASCADE,

    -- Casafari Raw Price Estimates
    casafari_fast_sell INT,
    casafari_fair_market INT,
    casafari_premium INT,
    casafari_comparables_count INT,

    -- Our Filtered Price Estimates (±20% land/area)
    filtered_fast_sell INT,
    filtered_fair_market INT,
    filtered_premium INT,
    filtered_comparables_count INT,
    filter_tolerance DECIMAL(3,2) DEFAULT 0.20,

    -- Market Statistics
    average_price INT,
    average_price_per_sqm INT,
    average_days_on_market INT,
    sold_last_6_months INT,

    -- Reference
    asking_price INT,
    casafari_link TEXT,
    search_params JSONB,

    -- Raw response for debugging
    raw_casafari_response JSONB,
    raw_filtered_comparables JSONB,

    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- =============================================================================
-- TABLE: listing_comparables
-- Stores individual comparable properties from Casafari
-- =============================================================================

CREATE TABLE IF NOT EXISTS listing_comparables (
    id BIGSERIAL PRIMARY KEY,
    listing_id BIGINT REFERENCES listings(id) ON DELETE CASCADE,

    -- Casafari Property Info
    casafari_property_id BIGINT NOT NULL,
    property_url TEXT,

    -- Classification
    price_bucket TEXT NOT NULL,  -- 'fast_sell', 'fair_market', 'premium'
    is_filtered BOOLEAN DEFAULT FALSE,  -- Whether it passed our ±20% filter
    similarity_score DECIMAL(4,3),

    -- Property Details
    sale_price INT,
    price_per_sqm INT,
    total_area INT,       -- m2_built
    living_area INT,      -- m2_useful
    plot_area INT,        -- m2_plot (CRITICAL for houses)
    bedrooms INT,
    bathrooms INT,

    -- Condition & Energy
    condition TEXT,
    construction_year INT,
    energy_rating TEXT,

    -- Location
    distance_km DECIMAL(4,2),
    address TEXT,
    zip_code TEXT,
    coordinates JSONB,

    -- Media
    photo_urls JSONB,

    -- Features
    features JSONB,
    property_type TEXT,

    created_at TIMESTAMPTZ DEFAULT NOW(),

    UNIQUE(listing_id, casafari_property_id)
);

-- Index for efficient querying
CREATE INDEX IF NOT EXISTS idx_listing_comparables_listing ON listing_comparables(listing_id);
CREATE INDEX IF NOT EXISTS idx_listing_comparables_bucket ON listing_comparables(listing_id, price_bucket);
CREATE INDEX IF NOT EXISTS idx_listing_comparables_filtered ON listing_comparables(listing_id, is_filtered);

-- =============================================================================
-- TABLE: listing_bracket_analyses
-- Stores full renovation analysis for each bracket
-- =============================================================================

CREATE TABLE IF NOT EXISTS listing_bracket_analyses (
    id BIGSERIAL PRIMARY KEY,
    listing_id BIGINT REFERENCES listings(id) ON DELETE CASCADE,

    -- Which bracket/view
    view_type TEXT NOT NULL,  -- 'casafari' or 'filtered'
    bracket TEXT NOT NULL,    -- 'fast_sell', 'fair_market', 'premium'

    -- Target & Gap
    target_price INT NOT NULL,
    asking_price INT NOT NULL,
    gap INT NOT NULL,

    -- Pricing (from KGEstimator)
    renovation_cost INT,
    pem_subtotal INT,         -- Presupuesto Ejecución Material
    overhead_profit INT,      -- 19%
    iva INT,                  -- 21%
    line_items_count INT,
    scope_of_work JSONB,      -- Categories and items

    -- Math
    total_investment INT,
    potential_margin INT,

    -- Timeline
    estimated_weeks_min INT,
    estimated_weeks_max INT,
    timeline_breakdown JSONB,

    -- Visuals
    before_photo_url TEXT,
    after_photo_url TEXT,

    -- Status
    status TEXT DEFAULT 'pending',  -- 'pending', 'processing', 'complete', 'failed'
    error_message TEXT,

    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW(),

    UNIQUE(listing_id, view_type, bracket)
);

-- Index for efficient querying
CREATE INDEX IF NOT EXISTS idx_bracket_analyses_listing ON listing_bracket_analyses(listing_id);

-- =============================================================================
-- RLS POLICIES
-- =============================================================================

ALTER TABLE listing_market_stats ENABLE ROW LEVEL SECURITY;
ALTER TABLE listing_comparables ENABLE ROW LEVEL SECURITY;
ALTER TABLE listing_bracket_analyses ENABLE ROW LEVEL SECURITY;

-- Public read access (for now)
CREATE POLICY "Allow public read for listing_market_stats"
    ON listing_market_stats FOR SELECT USING (true);

CREATE POLICY "Allow public read for listing_comparables"
    ON listing_comparables FOR SELECT USING (true);

CREATE POLICY "Allow public read for listing_bracket_analyses"
    ON listing_bracket_analyses FOR SELECT USING (true);

-- Service role can do everything
CREATE POLICY "Allow service role full access to listing_market_stats"
    ON listing_market_stats FOR ALL USING (true);

CREATE POLICY "Allow service role full access to listing_comparables"
    ON listing_comparables FOR ALL USING (true);

CREATE POLICY "Allow service role full access to listing_bracket_analyses"
    ON listing_bracket_analyses FOR ALL USING (true);

-- =============================================================================
-- COMMENTS
-- =============================================================================

COMMENT ON TABLE listing_market_stats IS 'Market statistics and price brackets from Casafari + our filtered calculations';
