ALTER TABLE public.pipeline_runs DROP CONSTRAINT pipeline_runs_status_check;
ALTER TABLE public.pipeline_runs
  ADD COLUMN run_id text NOT NULL DEFAULT gen_random_uuid()::text UNIQUE,
  ADD COLUMN config jsonb NOT NULL DEFAULT '{}',
  ADD COLUMN current_stage text,
  ADD COLUMN error_summary text,
  ADD COLUMN last_progress_at timestamptz,
  ADD CONSTRAINT pipeline_runs_current_status_check
    CHECK (status IN ('pending','queued','running','completed','complete','failed','cancelled','stopped'));

CREATE TABLE public.pipeline_jobs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  run_id text NOT NULL REFERENCES public.pipeline_runs(run_id) ON DELETE CASCADE,
  listing_id bigint NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE,
  stage text NOT NULL,
  job_type text NOT NULL,
  payload jsonb NOT NULL DEFAULT '{}',
  idempotency_key text NOT NULL UNIQUE,
  status text NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued','in_progress','succeeded','failed','cancelled')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  max_attempts integer NOT NULL DEFAULT 5 CHECK (max_attempts > 0),
  available_at timestamptz NOT NULL DEFAULT now(),
  locked_by text,
  locked_until timestamptz,
  last_heartbeat_at timestamptz,
  started_at timestamptz,
  finished_at timestamptz,
  error text,
  error_context jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX pipeline_jobs_claim ON public.pipeline_jobs(available_at,created_at)
  WHERE status = 'queued';
CREATE INDEX pipeline_jobs_run ON public.pipeline_jobs(run_id,created_at);
CREATE TABLE public.pipeline_job_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id uuid NOT NULL REFERENCES public.pipeline_jobs(id) ON DELETE CASCADE,
  event_type text NOT NULL,
  message text NOT NULL,
  data jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX pipeline_job_events_job ON public.pipeline_job_events(job_id,created_at);

-- Global queue ordering remains in SQL; V5/GLA predecessor gating remains in
-- pipeline_worker.py. Expired jobs follow the retained reaper/explicit retry path.
CREATE FUNCTION public.claim_pipeline_jobs(
  p_worker_id text, p_limit integer DEFAULT 10, p_lock_seconds integer DEFAULT 300
) RETURNS SETOF public.pipeline_jobs LANGUAGE plpgsql SET search_path = pg_catalog,public AS $$
BEGIN
  IF p_worker_id IS NULL OR btrim(p_worker_id) = '' OR length(p_worker_id) > 200
     OR p_limit IS NULL OR p_limit < 1 OR p_limit > 100
     OR p_lock_seconds IS NULL OR p_lock_seconds < 1 OR p_lock_seconds > 3600 THEN
    RAISE EXCEPTION 'Supply a worker identity, limit 1..100 and lease 1..3600 seconds'
      USING ERRCODE = '22023';
  END IF;
  RETURN QUERY
    WITH selected AS (
      SELECT j.id FROM public.pipeline_jobs j
      WHERE j.status = 'queued' AND j.available_at <= now()
        AND j.attempts < j.max_attempts
      ORDER BY j.available_at,j.created_at,j.id
      LIMIT p_limit FOR UPDATE SKIP LOCKED
    )
    UPDATE public.pipeline_jobs j SET
      status = 'in_progress', attempts = j.attempts + 1,
      locked_by = p_worker_id,
      locked_until = now() + make_interval(secs => p_lock_seconds),
      last_heartbeat_at = now(), started_at = coalesce(j.started_at,now()),
      finished_at = NULL, updated_at = now()
    FROM selected WHERE j.id = selected.id RETURNING j.*;
END;
$$;
CREATE FUNCTION public.pipeline_job_counts(p_run_id text)
RETURNS TABLE(status text,count bigint) LANGUAGE sql STABLE
SET search_path = pg_catalog,public AS $$
  SELECT j.status,count(*) FROM public.pipeline_jobs j
  WHERE j.run_id = p_run_id GROUP BY j.status;
$$;

