  UNIQUE(listing_id,strategy_name,dimension,room_name,bcca_code,description)
);
CREATE TABLE public.pipeline_cost_tracking (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  listing_id bigint NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE,
  run_id text NOT NULL REFERENCES public.pipeline_runs(run_id) ON DELETE CASCADE,
  run_started_at timestamptz,
  run_completed_at timestamptz,
  status text,
  total_calls integer NOT NULL DEFAULT 0,
  total_input_tokens bigint NOT NULL DEFAULT 0,
  total_output_tokens bigint NOT NULL DEFAULT 0,
  total_cost_regular numeric NOT NULL DEFAULT 0,
  total_cost_cached numeric NOT NULL DEFAULT 0,
  by_stage jsonb NOT NULL DEFAULT '{}',
  by_model jsonb NOT NULL DEFAULT '{}',
  last_stage text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(listing_id,run_id)
);

-- SOURCE: supabase/migrations/0005_boq_line_items_provenance.sql
-- Add provenance + reference fields for BOQ v3 (non-lossy, auditable)
alter table if exists public.boq_line_items
  add column if not exists room_id text,
  add column if not exists wall_id text,
  add column if not exists opening_id text,
  add column if not exists quantity_ref text,
  add column if not exists quantity_rule_id text,
  add column if not exists item_kind text,
  add column if not exists embedding_similarity real,
  add column if not exists embedding_top_k jsonb,
  add column if not exists provenance jsonb;

-- Update upsert RPC to accept new fields (preserve existing merge behavior).
create or replace function public.boq_line_items_upsert(rows jsonb)
returns integer
language plpgsql
as $$
declare
  inserted_count integer := 0;
begin
  with input_rows as (
    select * from jsonb_to_recordset(rows) as x(
      listing_id int,
      strategy_name text,
      dimension text,
      room_name text,
      scope_item_element text,
      bcca_code text,
      description text,
      quantity numeric,
      unit text,
      unit_price numeric,
      line_total numeric,
      labor_hours numeric,
      quantity_reasoning text,
      room_id text,
      wall_id text,
      opening_id text,
      quantity_ref text,
      quantity_rule_id text,
      item_kind text,
      embedding_similarity real,
      embedding_top_k jsonb,
      provenance jsonb
    )
  ), ins as (
    insert into public.boq_line_items (
      listing_id,
      strategy_name,
      dimension,
      room_name,
      scope_item_element,
      bcca_code,
      description,
      quantity,
      unit,
      unit_price,
      line_total,
      labor_hours,
      quantity_reasoning,
      room_id,
      wall_id,
      opening_id,
      quantity_ref,
      quantity_rule_id,
      item_kind,
      embedding_similarity,
      embedding_top_k,
      provenance
    )
    select
      listing_id,
      strategy_name,
      dimension,
      room_name,
      scope_item_element,
      bcca_code,
      description,
      quantity,
      unit,
      unit_price,
      line_total,
      labor_hours,
      quantity_reasoning,
      room_id,
      wall_id,
      opening_id,
      quantity_ref,
      quantity_rule_id,
      item_kind,
      embedding_similarity,
      embedding_top_k,
      provenance
    from input_rows
    on conflict (listing_id, strategy_name, dimension, room_name, bcca_code, description)
    do update set
      quantity = coalesce(public.boq_line_items.quantity, 0) + coalesce(excluded.quantity, 0),
      line_total = coalesce(public.boq_line_items.line_total, 0) + coalesce(excluded.line_total, 0),
      labor_hours = coalesce(public.boq_line_items.labor_hours, 0) + coalesce(excluded.labor_hours, 0),
      quantity_reasoning = left(
        case
          when excluded.quantity_reasoning is null or excluded.quantity_reasoning = '' then public.boq_line_items.quantity_reasoning
          when public.boq_line_items.quantity_reasoning is null or public.boq_line_items.quantity_reasoning = '' then excluded.quantity_reasoning
          else public.boq_line_items.quantity_reasoning || E'\n\n' || excluded.quantity_reasoning
        end,
        4000
      ),
      unit = coalesce(public.boq_line_items.unit, excluded.unit),
      unit_price = coalesce(public.boq_line_items.unit_price, excluded.unit_price),
      scope_item_element = coalesce(public.boq_line_items.scope_item_element, excluded.scope_item_element),
      room_id = coalesce(public.boq_line_items.room_id, excluded.room_id),
      wall_id = coalesce(public.boq_line_items.wall_id, excluded.wall_id),
      opening_id = coalesce(public.boq_line_items.opening_id, excluded.opening_id),
      quantity_ref = coalesce(public.boq_line_items.quantity_ref, excluded.quantity_ref),
      quantity_rule_id = coalesce(public.boq_line_items.quantity_rule_id, excluded.quantity_rule_id),
      item_kind = coalesce(public.boq_line_items.item_kind, excluded.item_kind),
      embedding_similarity = coalesce(public.boq_line_items.embedding_similarity, excluded.embedding_similarity),
      embedding_top_k = coalesce(public.boq_line_items.embedding_top_k, excluded.embedding_top_k),
      provenance = coalesce(public.boq_line_items.provenance, excluded.provenance)
    returning 1
  )
  select count(*) into inserted_count from ins;
  return inserted_count;
end;
$$;

-- SOURCE: backend/migrations/005_pipeline_run_status_source_of_truth.sql
-- Migration: 005_pipeline_run_status_source_of_truth
-- Purpose: Single source of truth for pipeline run status, stage timeline, and stuck-job reaping
-- Date: 2026-02-13
--
-- SUPERSEDED: The refresh_pipeline_run_status() function defined here has been
-- replaced by migration 010. This file is kept only for the ALTER TABLE and
-- trigger/reaper DDL. Do NOT re-apply the function definition from this file.

-- -----------------------------------------------------------------------------
-- 1) Add materialized run-status columns
-- -----------------------------------------------------------------------------
ALTER TABLE public.pipeline_runs
  ADD COLUMN IF NOT EXISTS jobs_queued integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS jobs_in_progress integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS jobs_succeeded integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS jobs_failed integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS jobs_total integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS stages jsonb NOT NULL DEFAULT '[]'::jsonb;


-- -----------------------------------------------------------------------------
-- 2) Single status computer for one run_id
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.refresh_pipeline_run_status(p_run_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
declare
  v_listing_id integer;
  v_config jsonb;
  v_is_v5 boolean := false;
  v_v5_job_types text[] := array[
    'v5_fetch_listing_snapshot',
    'fetch_comparables',
    'v5_fetch_comparables_snapshot',
    'v5_cluster_target_photos',
    'v5_room_tags',
    'v5_generate_target_pir_slots',
    'v5_select_median_comparable',
    'v5_cluster_selected_comparable_photos',
    'v5_generate_selected_comparable_room_pirs',
    'v5_delta_slots_market_standard',
    'v5_work_items_market_standard',
    'v5_smart_m2',
    'v5_bcca_match',
    'v5_quant_plan',
    'v5_forage',
    'v5_boq_assembly',
    'v5_finalize',
    'v5_eli5',
    'v5_architect_report',
    'v5_room_images'
  ];
  v_stage_order text[] := array[
    'snapshot',
    'comparables',
    'clustering',
    'v5_room_tags',
    'v5_pir',
    'v5_select',
    'v5_comparables',
    'v5_delta',
    'v5_delta_review',
    'v5_decompose',
    'v5_smart_m2',
    'v5_bcca_match',
    'v5_quant_plan',
    'v5_forage',
    'v5_boq_assembly',
    'v5_finalize',
    'v5_eli5',
    'v5_architect_report',
    'v5_room_images_defurnish',
    'v5_room_images_prompt_generation',
    'v5_room_images_style_consistency',
    'v5_room_images_photo_generation'
  ];
  v_jobs_queued integer := 0;
  v_jobs_in_progress integer := 0;
  v_jobs_succeeded integer := 0;
  v_jobs_failed integer := 0;
  v_jobs_total integer := 0;
  v_stages jsonb := '[]'::jsonb;
  v_current_stage text := null;
  v_error_summary text := null;
  v_run_status text := 'queued';
begin
  select listing_id, coalesce(config, '{}'::jsonb)
  into v_listing_id, v_config
  from public.pipeline_runs
  where run_id = p_run_id;

  if not found then
    return;
  end if;

  v_is_v5 := coalesce(v_config->>'pipeline', '') = 'v5';

  with filtered_jobs as (
    select j.*
    from public.pipeline_jobs j
    where j.run_id = p_run_id
      and (
        (v_is_v5 and j.job_type = any(v_v5_job_types))
        or (not v_is_v5)
      )
  )
  select
    coalesce(sum(case when status = 'queued' then 1 else 0 end), 0)::integer,
    coalesce(sum(case when status = 'in_progress' then 1 else 0 end), 0)::integer,
    coalesce(sum(case when status = 'succeeded' then 1 else 0 end), 0)::integer,
    coalesce(sum(case when status = 'failed' then 1 else 0 end), 0)::integer,
    coalesce(count(*), 0)::integer
  into
    v_jobs_queued, v_jobs_in_progress, v_jobs_succeeded, v_jobs_failed, v_jobs_total
  from filtered_jobs;

  with filtered_jobs as (
    select j.*
    from public.pipeline_jobs j
    where j.run_id = p_run_id
      and (
        (v_is_v5 and j.job_type = any(v_v5_job_types))
        or (not v_is_v5)
      )
  )
  select j.error
  into v_error_summary
  from filtered_jobs j
  where j.status = 'failed'
    and j.error is not null
  order by coalesce(j.updated_at, j.created_at) desc
  limit 1;

  if v_is_v5 then
    with filtered_jobs as (
      select j.*
      from public.pipeline_jobs j
      where j.run_id = p_run_id
        and j.job_type = any(v_v5_job_types)
    ),
    real_stage_counts as (
      select
        j.stage::text as stage,
        sum(case when j.status = 'queued' then 1 else 0 end)::integer as queued,
        sum(case when j.status = 'in_progress' then 1 else 0 end)::integer as in_progress,
        sum(case when j.status = 'succeeded' then 1 else 0 end)::integer as succeeded,
        sum(case when j.status = 'failed' then 1 else 0 end)::integer as failed
      from filtered_jobs j
      group by j.stage
    ),
    delta_review as (
      select
        'v5_delta_review'::text as stage,
        0::integer as queued,
        0::integer as in_progress,
        case when exists (
          select 1
          from public.unified_estimates ue
          where ue.listing_id = v_listing_id
            and ue.package_type = 'v5_delta_review_market_standard'
            and coalesce((ue.estimate_data->>'success')::boolean, false) = true
        ) then 1 else 0 end::integer as succeeded,
        case when exists (
          select 1
          from public.unified_estimates ue
          where ue.listing_id = v_listing_id
            and ue.package_type = 'v5_delta_review_market_standard'
            and coalesce((ue.estimate_data->>'success')::boolean, false) = false
        ) then 1 else 0 end::integer as failed
    ),
    room_images_state as (
      select
        case
          when coalesce((select failed from real_stage_counts where stage = 'v5_room_images'), 0) > 0 then 'failed'
          when coalesce((select in_progress from real_stage_counts where stage = 'v5_room_images'), 0) > 0 then 'in_progress'
          when coalesce((select queued from real_stage_counts where stage = 'v5_room_images'), 0) > 0 then 'queued'
          when coalesce((select succeeded from real_stage_counts where stage = 'v5_room_images'), 0) > 0 then 'succeeded'
          else 'unknown'
        end::text as state
    ),
    room_artifacts as (
      select 1 as ord, 'v5_room_images_defurnish'::text as stage, 'v5_room_images_defurnish_market_standard'::text as artifact_key
      union all select 2, 'v5_room_images_prompt_generation', 'v5_room_images_prompt_gen_market_standard'
      union all select 3, 'v5_room_images_style_consistency', 'v5_room_images_style_consistency_market_standard'
      union all select 4, 'v5_room_images_photo_generation', 'v5_generated_images_market_standard'
    ),
    room_done as (
      select
        ra.ord,
        ra.stage,
        exists (
          select 1
          from public.unified_estimates ue
          where ue.listing_id = v_listing_id
            and ue.package_type = ra.artifact_key
        ) as done
      from room_artifacts ra
    ),
    first_missing as (
      select min(ord)::integer as idx
      from room_done
      where done = false
    ),
    room_virtual_counts as (
      select
        rd.stage,
        case
          when rd.done then 0
          when ris.state = 'queued' then 1
          when fm.idx is not null and rd.ord > fm.idx then 1
          else 0
        end::integer as queued,
        case
          when rd.done then 0
          when ris.state = 'in_progress' and fm.idx = rd.ord then 1
          else 0
        end::integer as in_progress,
        case
          when rd.done or ris.state = 'succeeded' then 1
          else 0
        end::integer as succeeded,
        case
          when rd.done then 0
          when ris.state = 'failed' and fm.idx = rd.ord then 1
          else 0
        end::integer as failed
      from room_done rd
      cross join room_images_state ris
      cross join first_missing fm
    ),
    combined as (
      select stage, queued, in_progress, succeeded, failed from real_stage_counts
      union all
      select stage, queued, in_progress, succeeded, failed from delta_review
      union all
      select stage, queued, in_progress, succeeded, failed from room_virtual_counts
    ),
    combined_agg as (
      select
        stage,
        sum(queued)::integer as queued,
        sum(in_progress)::integer as in_progress,
        sum(succeeded)::integer as succeeded,
        sum(failed)::integer as failed
      from combined
      group by stage
    ),
    stage_order as (
      select so.stage, so.ord
      from unnest(v_stage_order) with ordinality as so(stage, ord)
      union all
      select ca.stage, 1000 + row_number() over (order by ca.stage)
      from combined_agg ca
      where not (ca.stage = any(v_stage_order))
    ),
    raw as (
      select
        so.ord,
        so.stage,
        coalesce(ca.queued, 0)::integer as queued,
        coalesce(ca.in_progress, 0)::integer as in_progress,
        coalesce(ca.succeeded, 0)::integer as succeeded,
        coalesce(ca.failed, 0)::integer as failed,
        case
          when coalesce(ca.failed, 0) > 0 then 'failed'
          when coalesce(ca.in_progress, 0) > 0 then 'in_progress'
          when coalesce(ca.queued, 0) > 0 then 'queued'
          when coalesce(ca.succeeded, 0) > 0 then 'succeeded'
          else 'unknown'
        end::text as status
      from stage_order so
      left join combined_agg ca on ca.stage = so.stage
      order by so.ord
    ),
    first_blocked as (
      select min(ord)::integer as ord
      from raw
      where status <> 'succeeded'
    ),
    normalized as (
      select
        r.ord,
        r.stage,
        case
          when fb.ord is not null and r.ord > fb.ord and r.status in ('succeeded', 'failed', 'in_progress')
            then greatest(1, r.queued)
          else r.queued
        end::integer as queued,
        case
          when fb.ord is not null and r.ord > fb.ord and r.status in ('succeeded', 'failed', 'in_progress')
            then 0
          else r.in_progress
        end::integer as in_progress,
        case
          when fb.ord is not null and r.ord > fb.ord and r.status in ('succeeded', 'failed', 'in_progress')
            then 0
          else r.succeeded
        end::integer as succeeded,
        case
          when fb.ord is not null and r.ord > fb.ord and r.status in ('succeeded', 'failed', 'in_progress')
            then 0
          else r.failed
        end::integer as failed
      from raw r
      cross join first_blocked fb
      order by r.ord
    ),
    normalized_first as (
      select min(ord)::integer as ord
      from normalized
      where not (succeeded > 0 and queued = 0 and in_progress = 0 and failed = 0)
    )
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'stage', n.stage,
            'queued', n.queued,
            'in_progress', n.in_progress,
            'succeeded', n.succeeded,
            'failed', n.failed
          )
          order by n.ord
        ),
        '[]'::jsonb
      ),
      (
        select n.stage
        from normalized n
        join normalized_first nf on n.ord = nf.ord
      )
    into v_stages, v_current_stage
    from normalized n;
  else
    with filtered_jobs as (
      select j.*
      from public.pipeline_jobs j
      where j.run_id = p_run_id
    ),
    grouped as (
      select
        j.stage::text as stage,
        min(j.created_at) as first_created,
        sum(case when j.status = 'queued' then 1 else 0 end)::integer as queued,
        sum(case when j.status = 'in_progress' then 1 else 0 end)::integer as in_progress,
        sum(case when j.status = 'succeeded' then 1 else 0 end)::integer as succeeded,
        sum(case when j.status = 'failed' then 1 else 0 end)::integer as failed
      from filtered_jobs j
      group by j.stage
    ),
    ordered as (
      select
        g.stage,
        g.queued,
        g.in_progress,
        g.succeeded,
        g.failed
      from grouped g
      order by g.first_created asc, g.stage asc
    )
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'stage', o.stage,
            'queued', o.queued,
            'in_progress', o.in_progress,
            'succeeded', o.succeeded,
            'failed', o.failed
          )
        ),
        '[]'::jsonb
      ),
      (
        select o.stage
        from ordered o
        where not (o.succeeded > 0 and o.queued = 0 and o.in_progress = 0 and o.failed = 0)
        limit 1
      )
    into v_stages, v_current_stage
    from ordered o;
  end if;

  if v_jobs_total = 0 then
    v_run_status := 'queued';
  elsif v_jobs_queued > 0 or v_jobs_in_progress > 0 then
    v_run_status := 'running';
  elsif v_jobs_failed > 0 then
    v_run_status := 'failed';
  else
    v_run_status := 'complete';
  end if;

  update public.pipeline_runs r
  set
    status = v_run_status,
    current_stage = v_current_stage,
    error_summary = case when v_run_status = 'failed' then v_error_summary else null end,
    jobs_queued = v_jobs_queued,
    jobs_in_progress = v_jobs_in_progress,
    jobs_succeeded = v_jobs_succeeded,
    jobs_failed = v_jobs_failed,
    jobs_total = v_jobs_total,
    stages = coalesce(v_stages, '[]'::jsonb),
    last_progress_at = now(),
    completed_at = case
      when v_run_status = 'complete' then coalesce(r.completed_at, now())
      else null
    end,
    updated_at = now()
  where r.run_id = p_run_id;
end;
$$;


-- -----------------------------------------------------------------------------
-- 3) Trigger wrapper on pipeline_jobs mutations
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public._pipeline_jobs_refresh_run_status_trg()
RETURNS trigger
LANGUAGE plpgsql
AS $$
declare
  v_run_id text;
begin
  v_run_id := coalesce(new.run_id, old.run_id);
  if v_run_id is not null then
    perform public.refresh_pipeline_run_status(v_run_id);
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;

drop trigger if exists pipeline_jobs_refresh_run_status on public.pipeline_jobs;
create trigger pipeline_jobs_refresh_run_status
after insert or update or delete
on public.pipeline_jobs
for each row
execute function public._pipeline_jobs_refresh_run_status_trg();


-- -----------------------------------------------------------------------------
-- 4) Stuck-job reaper
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.reap_stuck_pipeline_jobs(
  p_stale_seconds integer default 600,
  p_heartbeat_grace_seconds integer default 300,
  p_limit integer default 100
)
RETURNS integer
LANGUAGE plpgsql
AS $$
declare
  v_count integer := 0;
begin
  with stale as (
    select j.id
    from public.pipeline_jobs j
    where j.status = 'in_progress'
      and j.locked_until is not null
      and j.locked_until < (now() - make_interval(secs => greatest(0, coalesce(p_stale_seconds, 600))))
      and coalesce(j.last_heartbeat_at, j.started_at, j.updated_at, j.created_at)
            < (now() - make_interval(secs => greatest(0, coalesce(p_heartbeat_grace_seconds, 300))))
    order by j.locked_until asc
    limit greatest(1, coalesce(p_limit, 100))
  )
  update public.pipeline_jobs j
  set
    status = 'failed',
    error = 'Worker heartbeat expired (stuck in_progress reaped)',
    error_context = jsonb_build_object(
      'reason', 'heartbeat_expired',
      'reaped_at', now(),
      'stale_seconds', p_stale_seconds,
      'heartbeat_grace_seconds', p_heartbeat_grace_seconds
    ),
    locked_by = null,
    locked_until = null,
    finished_at = now(),
    updated_at = now()
  from stale s
  where j.id = s.id;

  get diagnostics v_count = row_count;
  return coalesce(v_count, 0);
end;
$$;


-- -----------------------------------------------------------------------------
-- 5) Backfill helper + initial backfill
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.backfill_pipeline_run_statuses(p_limit integer default null)
RETURNS integer
LANGUAGE plpgsql
AS $$
declare
  r record;
  v_count integer := 0;
begin
  for r in
    select pr.run_id
    from public.pipeline_runs pr
    order by pr.created_at desc
    limit case when p_limit is null then 2147483647 else greatest(1, p_limit) end
  loop
    perform public.refresh_pipeline_run_status(r.run_id);
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

select public.backfill_pipeline_run_statuses(null);

-- SOURCE: backend/migrations/009_gemini_call_log_and_run_costs_view.sql
-- 009_gemini_call_log_and_run_costs_view
--
-- WHY THIS MATTERS:
-- We want to measure the ACTUAL tokens sent/received from Gemini for every call.
-- That requires persisting per-call usage_metadata (source of truth), and deriving
-- totals from those rows (not from logs or in-memory counters that can race/reset).

create table if not exists public.gemini_call_log (
  id bigserial primary key,
  listing_id bigint not null,
  run_id text not null,
  job_id text,
  stage text not null,
  job_type text,
  model text not null,

  has_images boolean not null default false,
  pricing_tier text not null default 'standard', -- 'standard' | 'long'
  pricing_mode text not null default 'regular',  -- 'regular' | 'cached' (informational)

  prompt_tokens integer not null,
  output_tokens integer not null,
  thinking_tokens integer not null default 0,
  total_tokens integer not null,

  cost_regular numeric(12,6) not null,
  cost_cached numeric(12,6) not null,

  usage_metadata jsonb,
  request_meta jsonb,

  created_at timestamptz not null default now()
);

create index if not exists gemini_call_log_listing_run_idx
  on public.gemini_call_log(listing_id, run_id);

create index if not exists gemini_call_log_run_stage_idx
  on public.gemini_call_log(run_id, stage);

create index if not exists gemini_call_log_run_model_idx
  on public.gemini_call_log(run_id, model);

-- Aggregated, queryable source-of-truth for run costs.
-- PostgREST can select from this view directly.
create or replace view public.gemini_run_costs_v1 as
with totals as (
  select
    listing_id,
    run_id,
    count(*)::int as total_calls,
    coalesce(sum(prompt_tokens), 0)::bigint as total_input_tokens,
    coalesce(sum(output_tokens + thinking_tokens), 0)::bigint as total_output_tokens,
    coalesce(sum(cost_regular), 0)::numeric(12,6) as total_cost_regular,
    coalesce(sum(cost_cached), 0)::numeric(12,6) as total_cost_cached,
    min(created_at) as first_call_at,
    max(created_at) as last_call_at
  from public.gemini_call_log
  group by listing_id, run_id
),
stage_rollup as (
  select
    listing_id,
    run_id,
    stage,
    count(*)::int as calls,
    coalesce(sum(prompt_tokens), 0)::bigint as input_tokens,
    coalesce(sum(output_tokens), 0)::bigint as output_tokens,
    coalesce(sum(thinking_tokens), 0)::bigint as thinking_tokens,
    coalesce(sum(cost_regular), 0)::numeric(12,6) as cost_regular,
    coalesce(sum(cost_cached), 0)::numeric(12,6) as cost_cached
  from public.gemini_call_log
  group by listing_id, run_id, stage
),
model_rollup as (
  select
    listing_id,
    run_id,
    model,
    count(*)::int as calls,
    coalesce(sum(prompt_tokens), 0)::bigint as input_tokens,
    coalesce(sum(output_tokens), 0)::bigint as output_tokens,
    coalesce(sum(thinking_tokens), 0)::bigint as thinking_tokens,
    coalesce(sum(cost_regular), 0)::numeric(12,6) as cost_regular,
    coalesce(sum(cost_cached), 0)::numeric(12,6) as cost_cached
  from public.gemini_call_log
  group by listing_id, run_id, model
)
select
  t.listing_id,
  t.run_id,
  t.total_calls,
  t.total_input_tokens,
  t.total_output_tokens,
  t.total_cost_regular,
  t.total_cost_cached,
  coalesce(
    (
      select jsonb_object_agg(
        s.stage,
        jsonb_build_object(
          'calls', s.calls,
          'input_tokens', s.input_tokens,
          'output_tokens', s.output_tokens,
          'thinking_tokens', s.thinking_tokens,
          'cost_regular', s.cost_regular,
          'cost_cached', s.cost_cached
        )
      )
      from stage_rollup s
      where s.listing_id = t.listing_id and s.run_id = t.run_id
    ),
    '{}'::jsonb
  ) as by_stage,
  coalesce(
    (
      select jsonb_object_agg(
        m.model,
        jsonb_build_object(
          'calls', m.calls,
          'input_tokens', m.input_tokens,
          'output_tokens', m.output_tokens,
          'thinking_tokens', m.thinking_tokens,
          'cost_regular', m.cost_regular,
          'cost_cached', m.cost_cached
        )
      )
      from model_rollup m
      where m.listing_id = t.listing_id and m.run_id = t.run_id
    ),
    '{}'::jsonb
  ) as by_model,
  t.first_call_at,
  t.last_call_at
from totals t;

-- NOTE:
-- This view is later extended to support clear-from-stage reruns by excluding cleared rows
-- and adding a cleared_costs breakdown (see migration 010b).

-- SOURCE: backend/migrations/010b_gemini_call_log_clear_history.sql
-- 010b_gemini_call_log_clear_history
--
-- WHY THIS MATTERS:
-- Admin clear-from-stage reruns jobs in the SAME run_id. If we keep per-call cost rows,
-- a rerun would otherwise accumulate costs from multiple attempts.
--
-- Approach:
-- - Mark downstream call-log rows as cleared with a per-run sequence number.
-- - Exclude cleared rows from the default run totals.
-- - Keep cleared totals available as a per-clear breakdown.

create table if not exists public.gemini_clear_events (
  id bigserial primary key,
  listing_id bigint not null,
  run_id text not null,
  clear_seq integer not null,
  from_stage text not null,
  stages jsonb,
  note text,
  created_at timestamptz not null default now()
);

create unique index if not exists gemini_clear_events_run_seq_uidx
  on public.gemini_clear_events(run_id, clear_seq);

create index if not exists gemini_clear_events_listing_run_idx
  on public.gemini_clear_events(listing_id, run_id);

alter table public.gemini_call_log
  add column if not exists cleared_seq integer,
  add column if not exists cleared_at timestamptz,
  add column if not exists cleared_from_stage text;

create index if not exists gemini_call_log_run_cleared_idx
  on public.gemini_call_log(run_id, cleared_seq);

create or replace view public.gemini_run_costs_v1 as
with active as (
  select *
  from public.gemini_call_log
  where cleared_seq is null
),
active_totals as (
  select
    listing_id,
    run_id,
    count(*)::int as total_calls,
    coalesce(sum(prompt_tokens), 0)::bigint as total_input_tokens,
    coalesce(sum(output_tokens + thinking_tokens), 0)::bigint as total_output_tokens,
    coalesce(sum(cost_regular), 0)::numeric(12,6) as total_cost_regular,
    coalesce(sum(cost_cached), 0)::numeric(12,6) as total_cost_cached,
    min(created_at) as first_call_at,
    max(created_at) as last_call_at
  from active
  group by listing_id, run_id
),
active_stage_rollup as (
  select
    listing_id,
    run_id,
    stage,
    count(*)::int as calls,
    coalesce(sum(prompt_tokens), 0)::bigint as input_tokens,
    coalesce(sum(output_tokens), 0)::bigint as output_tokens,
    coalesce(sum(thinking_tokens), 0)::bigint as thinking_tokens,
    coalesce(sum(cost_regular), 0)::numeric(12,6) as cost_regular,
    coalesce(sum(cost_cached), 0)::numeric(12,6) as cost_cached
  from active
  group by listing_id, run_id, stage
),
active_model_rollup as (
  select
    listing_id,
    run_id,
    model,
    count(*)::int as calls,
    coalesce(sum(prompt_tokens), 0)::bigint as input_tokens,
    coalesce(sum(output_tokens), 0)::bigint as output_tokens,
    coalesce(sum(thinking_tokens), 0)::bigint as thinking_tokens,
    coalesce(sum(cost_regular), 0)::numeric(12,6) as cost_regular,
    coalesce(sum(cost_cached), 0)::numeric(12,6) as cost_cached
  from active
  group by listing_id, run_id, model
),
cleared_rollup as (
  select
    listing_id,
    run_id,
    cleared_seq,
    min(cleared_from_stage) as from_stage,
    min(cleared_at) as cleared_at,
    count(*)::int as calls,
    coalesce(sum(prompt_tokens), 0)::bigint as input_tokens,
    coalesce(sum(output_tokens + thinking_tokens), 0)::bigint as output_tokens,
    coalesce(sum(cost_regular), 0)::numeric(12,6) as cost_regular,
    coalesce(sum(cost_cached), 0)::numeric(12,6) as cost_cached
  from public.gemini_call_log
  where cleared_seq is not null
  group by listing_id, run_id, cleared_seq
)
select
  t.listing_id,
  t.run_id,
  t.total_calls,
  t.total_input_tokens,
  t.total_output_tokens,
  t.total_cost_regular,
  t.total_cost_cached,
  coalesce(
    (
      select jsonb_object_agg(
        s.stage,
        jsonb_build_object(
          'calls', s.calls,
          'input_tokens', s.input_tokens,
          'output_tokens', s.output_tokens,
          'thinking_tokens', s.thinking_tokens,
          'cost_regular', s.cost_regular,
          'cost_cached', s.cost_cached
        )
      )
      from active_stage_rollup s
      where s.listing_id = t.listing_id and s.run_id = t.run_id
    ),
    '{}'::jsonb
  ) as by_stage,
  coalesce(
    (
      select jsonb_object_agg(
        m.model,
        jsonb_build_object(
          'calls', m.calls,
          'input_tokens', m.input_tokens,
          'output_tokens', m.output_tokens,
          'thinking_tokens', m.thinking_tokens,
          'cost_regular', m.cost_regular,
          'cost_cached', m.cost_cached
        )
      )
      from active_model_rollup m
      where m.listing_id = t.listing_id and m.run_id = t.run_id
    ),
    '{}'::jsonb
  ) as by_model,
  t.first_call_at,
  t.last_call_at,
  coalesce(
    (
      select jsonb_object_agg(
        cr.cleared_seq::text,
        jsonb_build_object(
          'from_stage', cr.from_stage,
          'cleared_at', cr.cleared_at,
          'calls', cr.calls,
          'input_tokens', cr.input_tokens,
          'output_tokens', cr.output_tokens,
          'cost_regular', cr.cost_regular,
          'cost_cached', cr.cost_cached
        )
      )
      from cleared_rollup cr
      where cr.listing_id = t.listing_id and cr.run_id = t.run_id
    ),
    '{}'::jsonb
  ) as cleared_costs
from active_totals t;

-- SOURCE: backend/migrations/011_refresh_pipeline_run_status_remove_architect_report.sql
-- Migration 011: Remove deprecated v5_architect_report from V5 status normalization
--
-- WHY THIS MATTERS
-- - We deprecated the architect report pipeline stage/job.
-- - The backend V5 stage registry no longer includes it.
-- - Supabase function `public.refresh_pipeline_run_status()` still listed it in the
--   V5 stage order + job type allowlist, which can confuse admin progress semantics.
--
-- This migration keeps the database status source-of-truth aligned with the codebase.

create or replace function public.refresh_pipeline_run_status(p_run_id text)
returns void
language plpgsql
security definer
as $function$
declare
  v_run record;
  v_is_v5 boolean := false;
  v_listing_id integer := null;
  v_run_created_at timestamptz := null;

  v_jobs_queued integer := 0;
  v_jobs_in_progress integer := 0;
  v_jobs_succeeded integer := 0;
  v_jobs_failed integer := 0;
  v_jobs_cancelled integer := 0;
  v_jobs_total integer := 0;

  v_stages jsonb := '[]'::jsonb;
  v_current_stage text := null;
  v_run_status text := null;
  v_error_summary text := null;

  v_stage_order text[] := array[
    'snapshot',
    'comparables',
    'clustering',
    'v5_room_tags',
    'v5_pir',
    'v5_select',
    'v5_comparables',
    'v5_delta',
    'v5_delta_review',
    'v5_decompose',
    'v5_smart_m2',
    'v5_bcca_match',
    'v5_quant_plan',
    'v5_forage',
    'v5_boq_assembly',
    'v5_finalize',
    'v5_eli5',
    'v5_room_images',
    'v5_room_images_defurnish',
    'v5_room_images_prompt_generation',
    'v5_room_images_style_consistency',
    'v5_room_images_photo_generation'
  ];

  v_v5_job_types text[] := array[
    'v5_fetch_listing_snapshot',
    'fetch_comparables',
    'v5_fetch_comparables_snapshot',
    'v5_cluster_target_photos',
    'v5_room_tags',
    'v5_generate_target_pir_slots',
    'v5_select_median_comparable',
    'v5_cluster_selected_comparable_photos',
    'v5_generate_selected_comparable_room_pirs',
    'v5_delta_slots_market_standard',
    'v5_work_items_market_standard',
    'v5_smart_m2',
    'v5_bcca_match',
    'v5_quant_plan',
    'v5_forage',
    'v5_boq_assembly',
    'v5_finalize',
    'v5_eli5',
    'v5_room_images'
  ];
begin
  select *
  into v_run
  from public.pipeline_runs
  where run_id = p_run_id
  limit 1;

  if not found then
    return;
  end if;

  v_listing_id := v_run.listing_id;
  v_is_v5 := coalesce((v_run.config->>'pipeline') = 'v5', false);
  v_run_created_at := v_run.created_at;

  if v_is_v5 then
    with filtered_jobs as (
      select j.*
      from public.pipeline_jobs j
      where j.run_id = p_run_id
        and j.job_type = any(v_v5_job_types)
    ),
    real_stage_counts as (
      select
        j.stage::text as stage,
        sum(case when j.status = 'queued' then 1 else 0 end)::integer as queued,
        sum(case when j.status = 'in_progress' then 1 else 0 end)::integer as in_progress,
        sum(case when j.status = 'succeeded' then 1 else 0 end)::integer as succeeded,
        sum(case when j.status = 'failed' then 1 else 0 end)::integer as failed
      from filtered_jobs j
      group by j.stage
    ),
    delta_stage as (
      select
        coalesce((select queued from real_stage_counts where stage = 'v5_delta'), 0)::integer as queued,
        coalesce((select in_progress from real_stage_counts where stage = 'v5_delta'), 0)::integer as in_progress,
        coalesce((select succeeded from real_stage_counts where stage = 'v5_delta'), 0)::integer as succeeded,
        coalesce((select failed from real_stage_counts where stage = 'v5_delta'), 0)::integer as failed
    ),
    delta_review_exists as (
      select
        exists (
          select 1
          from public.unified_estimates ue
          where ue.listing_id = v_listing_id
            and ue.package_type = 'v5_delta_review_market_standard'
            and coalesce(ue.generated_at, ue.updated_at) >= v_run_created_at
        ) as exists_any,
        exists (
          select 1
          from public.unified_estimates ue
          where ue.listing_id = v_listing_id
            and ue.package_type = 'v5_delta_review_market_standard'
            and coalesce(ue.generated_at, ue.updated_at) >= v_run_created_at
            and coalesce((ue.estimate_data->>'success')::boolean, false) = true
        ) as success_true,
        exists (
          select 1
          from public.unified_estimates ue
          where ue.listing_id = v_listing_id
            and ue.package_type = 'v5_delta_review_market_standard'
            and coalesce(ue.generated_at, ue.updated_at) >= v_run_created_at
            and coalesce((ue.estimate_data->>'success')::boolean, false) = false
        ) as success_false
    ),
    delta_review as (
      select
        'v5_delta_review'::text as stage,
        case
          when dre.exists_any then 0
          when ds.succeeded > 0 then 0
          else ds.queued
        end::integer as queued,
        case
          when dre.exists_any then 0
          when ds.succeeded > 0 then 0
          else ds.in_progress
        end::integer as in_progress,
        case
          when dre.exists_any and dre.success_true then 1
          else 0
        end::integer as succeeded,
        case
          when dre.exists_any and dre.success_false then 1
          when not dre.exists_any and ds.succeeded > 0 then 1
          else 0
        end::integer as failed
      from delta_stage ds
      cross join delta_review_exists dre
    ),
    room_images_state as (
      select
        case
          when coalesce((select failed from real_stage_counts where stage = 'v5_room_images'), 0) > 0 then 'failed'
          when coalesce((select in_progress from real_stage_counts where stage = 'v5_room_images'), 0) > 0 then 'in_progress'
          when coalesce((select queued from real_stage_counts where stage = 'v5_room_images'), 0) > 0 then 'queued'
          when coalesce((select succeeded from real_stage_counts where stage = 'v5_room_images'), 0) > 0 then 'succeeded'
          else 'unknown'
        end::text as state
    ),
    room_artifacts as (
      select 1 as ord, 'v5_room_images_defurnish'::text as stage, 'v5_room_images_defurnish_market_standard'::text as artifact_key
      union all select 2, 'v5_room_images_prompt_generation', 'v5_room_images_prompt_generation_market_standard'
      union all select 3, 'v5_room_images_style_consistency', 'v5_room_images_style_consistency_market_standard'
      union all select 4, 'v5_room_images_photo_generation', 'v5_generated_images_market_standard'
    ),
    room_done as (
      select
        ra.ord,
        ra.stage,
        exists (
          select 1
          from public.unified_estimates ue
          where ue.listing_id = v_listing_id
            and ue.package_type = ra.artifact_key
            and coalesce(ue.generated_at, ue.updated_at) >= v_run_created_at
        ) as done
      from room_artifacts ra
    ),
    first_missing as (
      select min(ord)::integer as idx
      from room_done
      where done = false
    ),
    room_virtual_counts as (
      select
        rd.stage,
        case
          when rd.done then 0
          when ris.state = 'unknown' then 0
          when ris.state = 'queued' then 1
          when fm.idx is not null and rd.ord >= fm.idx then 1
          else 0
        end::integer as queued,
        case
          when rd.done then 0
          when ris.state = 'unknown' then 0
          when ris.state = 'in_progress' and fm.idx = rd.ord then 1
          else 0
        end::integer as in_progress,
        case
          when rd.done or ris.state = 'succeeded' then 1
          else 0
        end::integer as succeeded,
        case
          when rd.done then 0
          when ris.state = 'unknown' then 0
          when ris.state = 'failed' and fm.idx = rd.ord then 1
          else 0
        end::integer as failed
      from room_done rd
      cross join room_images_state ris
      cross join first_missing fm
    ),
    combined as (
      select stage, queued, in_progress, succeeded, failed from real_stage_counts
      union all
      select stage, queued, in_progress, succeeded, failed from delta_review
      union all
      select stage, queued, in_progress, succeeded, failed from room_virtual_counts
    ),
    combined_agg as (
      select
        stage,
        sum(queued)::integer as queued,
        sum(in_progress)::integer as in_progress,
        sum(succeeded)::integer as succeeded,
        sum(failed)::integer as failed
      from combined
      group by stage
    ),
    stage_order as (
      select so.stage, so.ord
      from unnest(v_stage_order) with ordinality as so(stage, ord)
      union all
      select ca.stage, 1000 + row_number() over (order by ca.stage)
      from combined_agg ca
      where not (ca.stage = any(v_stage_order))
    ),
    raw as (
      select
        so.ord,
        so.stage,
        coalesce(ca.queued, 0)::integer as queued,
        coalesce(ca.in_progress, 0)::integer as in_progress,
        coalesce(ca.succeeded, 0)::integer as succeeded,
        coalesce(ca.failed, 0)::integer as failed,
        case
          when coalesce(ca.failed, 0) > 0 then 'failed'
          when coalesce(ca.in_progress, 0) > 0 then 'in_progress'
          when coalesce(ca.queued, 0) > 0 then 'queued'
          when coalesce(ca.succeeded, 0) > 0 then 'succeeded'
          else 'unknown'
        end::text as status
      from stage_order so
      left join combined_agg ca on ca.stage = so.stage
      order by so.ord
    ),
    first_blocked as (
      select min(ord)::integer as ord
      from raw
      where status <> 'succeeded'
    ),
    normalized as (
      select
        r.ord,
        r.stage,
        case
          when fb.ord is not null and r.ord > fb.ord and r.status in ('succeeded', 'failed', 'in_progress')
            then greatest(1, r.queued)
          else r.queued
        end::integer as queued,
        case
          when fb.ord is not null and r.ord > fb.ord and r.status in ('succeeded', 'failed', 'in_progress')
            then 0
          else r.in_progress
        end::integer as in_progress,
        case
          when fb.ord is not null and r.ord > fb.ord and r.status in ('succeeded', 'failed', 'in_progress')
            then 0
          else r.succeeded
        end::integer as succeeded,
        case
          when fb.ord is not null and r.ord > fb.ord and r.status in ('succeeded', 'failed', 'in_progress')
            then 0
          else r.failed
        end::integer as failed
      from raw r
      cross join first_blocked fb
      order by r.ord
    ),
    normalized_first as (
      select min(ord)::integer as ord
      from normalized
      where not (succeeded > 0 and queued = 0 and in_progress = 0 and failed = 0)
    )
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'stage', n.stage,
            'queued', n.queued,
            'in_progress', n.in_progress,
            'succeeded', n.succeeded,
            'failed', n.failed
          )
          order by n.ord
        ),
        '[]'::jsonb
      ),
      (
        select n.stage
        from normalized n
        join normalized_first nf on n.ord = nf.ord
      )
    into v_stages, v_current_stage
    from normalized n;
  else
    with filtered_jobs as (
      select j.*
      from public.pipeline_jobs j
      where j.run_id = p_run_id
    ),
    grouped as (
      select
        j.stage::text as stage,
        min(j.created_at) as first_created,
        sum(case when j.status = 'queued' then 1 else 0 end)::integer as queued,
        sum(case when j.status = 'in_progress' then 1 else 0 end)::integer as in_progress,
        sum(case when j.status = 'succeeded' then 1 else 0 end)::integer as succeeded,
        sum(case when j.status = 'failed' then 1 else 0 end)::integer as failed
      from filtered_jobs j
      group by j.stage
    ),
    ordered as (
      select
        g.stage,
        g.queued,
        g.in_progress,
        g.succeeded,
        g.failed
      from grouped g
      order by g.first_created asc, g.stage asc
    )
    select
      coalesce(
        jsonb_agg(
          jsonb_build_object(
            'stage', o.stage,
            'queued', o.queued,
            'in_progress', o.in_progress,
            'succeeded', o.succeeded,
            'failed', o.failed
          )
        ),
        '[]'::jsonb
      ),
      (
        select o.stage
        from ordered o
        where not (o.succeeded > 0 and o.queued = 0 and o.in_progress = 0 and o.failed = 0)
        limit 1
      )
    into v_stages, v_current_stage
    from ordered o;
  end if;

  if v_is_v5 then
    select
      sum(case when j.status = 'queued' then 1 else 0 end)::integer,
      sum(case when j.status = 'in_progress' then 1 else 0 end)::integer,
      sum(case when j.status = 'succeeded' then 1 else 0 end)::integer,
      sum(case when j.status = 'failed' then 1 else 0 end)::integer,
      sum(case when j.status = 'cancelled' then 1 else 0 end)::integer,
      count(*)::integer
    into v_jobs_queued, v_jobs_in_progress, v_jobs_succeeded, v_jobs_failed, v_jobs_cancelled, v_jobs_total
    from public.pipeline_jobs j
    where j.run_id = p_run_id
      and j.job_type = any(v_v5_job_types);
  else
    select
      sum(case when j.status = 'queued' then 1 else 0 end)::integer,
      sum(case when j.status = 'in_progress' then 1 else 0 end)::integer,
      sum(case when j.status = 'succeeded' then 1 else 0 end)::integer,
      sum(case when j.status = 'failed' then 1 else 0 end)::integer,
      sum(case when j.status = 'cancelled' then 1 else 0 end)::integer,
      count(*)::integer
    into v_jobs_queued, v_jobs_in_progress, v_jobs_succeeded, v_jobs_failed, v_jobs_cancelled, v_jobs_total
    from public.pipeline_jobs j
    where j.run_id = p_run_id;
  end if;

  if v_jobs_total = 0 then
    v_run_status := 'queued';
  elsif v_jobs_queued > 0 or v_jobs_in_progress > 0 then
    v_run_status := 'running';
  elsif v_jobs_cancelled > 0 then
    v_run_status := 'stopped';
  elsif v_jobs_failed > 0 then
    v_run_status := 'failed';
  else
    v_run_status := 'complete';
  end if;

  if v_jobs_failed > 0 then
    select j.error
    into v_error_summary
    from public.pipeline_jobs j
    where j.run_id = p_run_id
      and j.status = 'failed'
      and j.error is not null
    order by coalesce(j.updated_at, j.created_at) desc
    limit 1;
  end if;

  update public.pipeline_runs r
  set
    status = v_run_status,
    current_stage = v_current_stage,
    error_summary = case when v_run_status = 'failed' then v_error_summary else null end,
    jobs_queued = v_jobs_queued,
    jobs_in_progress = v_jobs_in_progress,
    jobs_succeeded = v_jobs_succeeded,
    jobs_failed = v_jobs_failed,
    jobs_total = v_jobs_total,
    stages = coalesce(v_stages, '[]'::jsonb),
    last_progress_at = now(),
    completed_at = case
      when v_run_status = 'complete' then coalesce(r.completed_at, now())
      else null
    end,
    updated_at = now()
  where r.run_id = p_run_id;
end;
$function$;

-- SOURCE: supabase/migrations/202611010001_service_only_research_writes.sql
-- Keep the original shared-read contracts; scope backend writes to their role.

DO $hardening$
DECLARE
  target text;
  policy_name text;
BEGIN
  IF to_regclass('public.due_diligence_research') IS NOT NULL THEN
    DROP POLICY IF EXISTS "Allow all access to due_diligence_research" ON public.due_diligence_research;
    DROP POLICY IF EXISTS "Recipient service manages due diligence" ON public.due_diligence_research;
    CREATE POLICY "Recipient service manages due diligence" ON public.due_diligence_research
      FOR ALL TO service_role USING (true) WITH CHECK (true);
    REVOKE ALL ON TABLE public.due_diligence_research FROM anon, authenticated;
  END IF;
  FOREACH target IN ARRAY ARRAY['listing_market_stats','listing_comparables','listing_bracket_analyses'] LOOP
    IF to_regclass(format('public.%I', target)) IS NOT NULL THEN
      policy_name := 'Allow service role full access to ' || target;
      EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', policy_name, target);
      EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO service_role USING (true) WITH CHECK (true)', policy_name, target);
      -- The distinct public SELECT policies in 009 are intentionally retained.
      EXECUTE format('REVOKE INSERT, UPDATE, DELETE ON TABLE public.%I FROM anon, authenticated', target);
    END IF;
  END LOOP;
  FOREACH target IN ARRAY ARRAY['property_intelligence_reports','comparative_gap_analyses','aggregated_gap_analyses'] LOOP
    IF to_regclass(format('public.%I', target)) IS NOT NULL THEN
      FOR policy_name IN SELECT policyname FROM pg_policies
        WHERE schemaname='public' AND tablename=target
          AND policyname IN ('Allow service insert','Allow service update') LOOP
        EXECUTE format('ALTER POLICY %I ON public.%I TO service_role', policy_name, target);
      END LOOP;
      IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename=target AND policyname='Allow read access') THEN
        -- Original schema comments specify authenticated shared reads.
        EXECUTE format('ALTER POLICY %I ON public.%I TO authenticated', 'Allow read access', target);
      END IF;
      EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon', target);
      EXECUTE format('REVOKE INSERT, UPDATE, DELETE ON TABLE public.%I FROM authenticated', target);
    END IF;
  END LOOP;
END
$hardening$;

-- SOURCE: db/bootstrap/private-backend.sql
-- The native frontend talks to the FastAPI server. Its database is service-only.
-- Apply these grants within the same fresh-install transaction as the retained DDL.
DO $security$
DECLARE
  item record;
BEGIN
  FOR item IN SELECT tablename FROM pg_tables WHERE schemaname='public'
    AND NOT EXISTS (SELECT 1 FROM pg_depend d
      WHERE d.classid='pg_class'::regclass AND d.objid = format('public.%I',tablename)::regclass AND d.deptype='e')
  LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',item.tablename);
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC,anon,authenticated',item.tablename);
    EXECUTE format('GRANT ALL ON TABLE public.%I TO service_role',item.tablename);
  END LOOP;
END;
$security$;
-- Retained SECURITY DEFINER RPCs are callable only by the trusted backend.
DO $objects$
DECLARE item record;
BEGIN
  FOR item IN SELECT p.oid::regprocedure AS signature FROM pg_proc p
    JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'
    AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e') LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',item.signature);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',item.signature);
  END LOOP;
  FOR item IN SELECT c.oid::regclass AS name FROM pg_class c
    JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind='S'
    AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=c.oid AND d.deptype='e') LOOP
    EXECUTE format('REVOKE ALL ON SEQUENCE %s FROM PUBLIC,anon,authenticated',item.name);
    EXECUTE format('GRANT ALL ON SEQUENCE %s TO service_role',item.name);
  END LOOP;
END;
$objects$;
REVOKE ALL ON public.gemini_run_costs_v1 FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.gemini_run_costs_v1 TO service_role;

COMMIT;
